COMMENT ON COLUMN sms_message.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN sms_message.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_sms_message_tenant ON sms_message (tenant_id, created_at);
CREATE INDEX ix_sms_message_msisdn ON sms_message (msisdn);
CREATE INDEX ix_sms_message_provider_message_id ON sms_message (provider_message_id);
CREATE INDEX ix_sms_message_sms_command_id ON sms_message (sms_command_id);
CREATE INDEX ix_sms_message_reply_to_id ON sms_message (reply_to_id);
CREATE INDEX ix_sms_message_wallet_transaction_id ON sms_message (wallet_transaction_id);
CREATE INDEX ix_sms_message_notification_id ON sms_message (notification_id);
ALTER TABLE sms_message ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON sms_message USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_sms_message_touch BEFORE UPDATE ON sms_message FOR EACH ROW EXECUTE FUNCTION touch_row();

-- Transactional outbox: events are written here in the same transaction as the
-- state change and relayed to Kafka by the outbox relay (Debezium).
CREATE TABLE outbox (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id       uuid NOT NULL,
  aggregate_type  varchar(64) NOT NULL,
  aggregate_id    uuid NOT NULL,
  event_type      varchar(128) NOT NULL,
  payload         jsonb NOT NULL,
  headers         jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_outbox_created ON outbox (created_at);

-- Idempotency keys for POST requests (24h retention).
CREATE TABLE idempotency_key (
  tenant_id       uuid NOT NULL,
  key             varchar(128) NOT NULL,
  request_hash    varchar(64) NOT NULL,
  response_status integer,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, key)
);

-- Runtime access for the non-superuser application role (RLS does not apply to superusers).
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'meridian_app') THEN
    GRANT USAGE ON SCHEMA channel TO meridian_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA channel TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA channel GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
